#!/usr/bin/env python3
"""sinta_protocol.py — validator for SINTA Provenance Exchange Protocol v1.0."""
import json, sys

REGISTERS = {"FACT", "LOGIC", "OPINION", "ACTION", "SENSE"}
STATUSES = {"RAW", "ASSUMED", "INFERRED", "VERIFIED", "PARKED", "RETRACTED"}
REQUIRED = ("type", "claim", "evidence", "boundary", "recipe")

def validate(record, author=None):
    problems = []
    if not isinstance(record, dict):
        return ["record is not an object"]
    for field in REQUIRED:
        if field not in record or record[field] in (None, ""):
            problems.append(f"missing required field: {field}")
    rtype = record.get("type")
    if rtype is not None and rtype.upper() not in REGISTERS:
        problems.append(f"type '{rtype}' not in registers {sorted(REGISTERS)}")
    status = record.get("status", "ASSUMED")
    if status.upper() not in STATUSES:
        problems.append(f"status '{status}' not on ladder {sorted(STATUSES)}")
    boundary = record.get("boundary", "")
    if boundary and boundary.strip().lower() in ("none","n/a","not applicable","everything","all"):
        problems.append("boundary looks like a dodge; a boundary names what was NOT checked")
    if status == "VERIFIED" and not record.get("recipe"):
        problems.append("VERIFIED record requires a RECIPE for independent reproduction")
    verified_by = record.get("verified_by")
    if verified_by:
        if isinstance(verified_by, list):
            for v in verified_by:
                if author and v == author:
                    problems.append("self-verification: author verified own claim")
        elif author and verified_by == author:
            problems.append("self-verification: author verified own claim")
    if rtype and rtype.upper() == "OPINION" and status == "VERIFIED":
        problems.append("OPINION can never be VERIFIED (type promise: opinion is not fact)")
    if rtype and rtype.upper() == "SENSE" and status in ("VERIFIED","INFERRED"):
        problems.append("SENSE can never be load-bearing (VERIFIED/INFERRED)")
    if status == "VERIFIED":
        checks = record.get("checks")
        if not checks or "run" not in checks or "passed" not in checks:
            problems.append("VERIFIED requires checks: {run: N, passed: M}")
        elif checks.get("passed", 0) < 1:
            problems.append("VERIFIED with zero passed checks is vacuous green")
    return problems

def main():
    args = sys.argv[1:]
    check_mode = False
    if args and args[0] == "--check":
        check_mode = True; args = args[1:]
    if not args:
        print("usage: sinta_protocol.py [--check] record.json"); return 2
    record = json.load(open(args[0]))
    problems = validate(record, record.get("author"))
    if not problems:
        print(f"VALID: {record.get('type','?')} / {record.get('status','ASSUMED')} — {str(record.get('claim',''))[:80]}")
        return 0 if check_mode else None
    for p in problems:
        print(f"VIOLATION: {p}")
    return 1 if check_mode else None

if __name__ == "__main__":
    sys.exit(main() or 0)
